<?php

namespace App\Http\Controllers;

use App\Models\Category;
use App\Models\Product;
use App\Models\Promotion;
use App\Models\Store;
use App\Support\Seo;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Http\Response;
use Illuminate\Support\Carbon;

/**
 * The two files a search engine looks for before it looks at anything else.
 *
 * Served from routes rather than dropped in public/ so both can name the site's
 * real domain, whichever one it is deployed on, and so the sitemap follows the
 * catalogue instead of being regenerated by hand.
 */
class SeoController extends Controller
{
    public function robots(): Response
    {
        $lines = [
            'User-agent: *',
            'Allow: /',
            // The panel and the inquiry endpoint have nothing to index.
            'Disallow: /admin',
            'Disallow: /admin/',
            'Disallow: /inquiry',
            'Disallow: /search/suggest',
            // One visitor's search is not a page — see Seo::robots().
            'Disallow: /*?search=',
            'Disallow: /*&search=',
            '',
            'Sitemap: '.url('/sitemap.xml'),
            '',
        ];

        return response(implode("\n", $lines), 200, ['Content-Type' => 'text/plain; charset=UTF-8']);
    }

    /**
     * Every page worth indexing, including the catalogue's category and
     * variety views — those are deep-linked from both category pages and are
     * the closest thing this site has to a product page.
     */
    public function sitemap(): Response
    {
        $urls = [
            ['/', '1.0', 'weekly', $this->latestOf(Product::class)],
            ['/about', '0.7', 'yearly', null],
            ['/stores', '0.8', 'monthly', $this->latestOf(Store::class)],
            ['/categories', '0.9', 'monthly', $this->latestOf(Category::class)],
            ['/b2b-categories', '0.9', 'monthly', $this->latestOf(Category::class)],
            ['/products', '0.9', 'weekly', $this->latestOf(Product::class)],
            ['/promotions', '0.8', 'weekly', $this->latestOf(Promotion::class)],
            ['/contact', '0.7', 'yearly', null],
        ];

        $categories = Category::active()
            ->ordered()
            ->with(['subcategories' => fn ($query) => $query->where('is_active', true)->orderBy('sort_order')])
            ->get();

        foreach ($categories as $category) {
            $segment = $category->type === Category::TYPE_B2B ? 'b2b' : 'retail';
            $base = '/products?segment='.$segment.'&category='.rawurlencode($category->name);

            $urls[] = [$base, '0.8', 'weekly', $category->updated_at];

            foreach ($category->subcategories as $subcategory) {
                $urls[] = [
                    $base.'&variety='.rawurlencode($subcategory->name),
                    '0.6',
                    'weekly',
                    $subcategory->updated_at,
                ];
            }
        }

        // Every product now has a page of its own, and those are the pages
        // worth ranking — one URL per pack rather than one for the whole shelf.
        Product::query()
            ->active()
            ->with('subcategory.category')
            ->ordered()
            ->get()
            ->filter(fn (Product $product) => filled($product->slug)
                && $product->subcategory?->is_active
                && $product->subcategory->category?->is_active)
            ->each(function (Product $product) use (&$urls) {
                $urls[] = ['/products/'.$product->slug, '0.7', 'monthly', $product->updated_at];
            });

        $xml = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'];

        foreach ($urls as [$path, $priority, $frequency, $lastmod]) {
            $xml[] = '  <url>';
            $xml[] = '    <loc>'.htmlspecialchars(Seo::url($path), ENT_XML1).'</loc>';

            if ($lastmod instanceof Carbon) {
                $xml[] = '    <lastmod>'.$lastmod->toDateString().'</lastmod>';
            }

            $xml[] = '    <changefreq>'.$frequency.'</changefreq>';
            $xml[] = '    <priority>'.$priority.'</priority>';
            $xml[] = '  </url>';
        }

        $xml[] = '</urlset>';

        return response(implode("\n", $xml), 200, ['Content-Type' => 'application/xml; charset=UTF-8']);
    }

    /**
     * When the content behind a page last changed, so a crawler that has seen
     * it before knows whether to come back in.
     *
     * @param  class-string<Model>  $model
     */
    private function latestOf(string $model): ?Carbon
    {
        return $model::query()->max('updated_at')
            ? Carbon::parse($model::query()->max('updated_at'))
            : null;
    }
}
